import { expect } from "chai";
import { ethers } from "hardhat";
import { DonnyRound } from "../typechain-types";
import { Contract } from "ethers";

describe("DonnyRound", function () {
  let donnyRound: DonnyRound;
  let cUSD: Contract;
  let owner: any;
  let player1: any;
  let player2: any;
  let player3: any;
  let charity: any;

  const ENTRY_FEE = ethers.parseEther("2");
  const INITIAL_BALANCE = ethers.parseEther("100");

  beforeEach(async function () {
    [owner, player1, player2, player3, charity] = await ethers.getSigners();

    // Deploy mock ERC20 token for testing
    const MockERC20 = await ethers.getContractFactory("MockERC20");
    cUSD = await MockERC20.deploy("cUSD", "cUSD", 18);
    await cUSD.waitForDeployment();

    // Mint tokens to players
    await cUSD.mint(player1.address, INITIAL_BALANCE);
    await cUSD.mint(player2.address, INITIAL_BALANCE);
    await cUSD.mint(player3.address, INITIAL_BALANCE);

    // Deploy DonnyRound
    const DonnyRound = await ethers.getContractFactory("DonnyRound");
    donnyRound = await DonnyRound.deploy(
      await cUSD.getAddress(),
      charity.address
    );
    await donnyRound.waitForDeployment();
  });

  describe("Deployment", function () {
    it("Should set the correct cUSD address", async function () {
      expect(await donnyRound.cUSD()).to.equal(await cUSD.getAddress());
    });

    it("Should set the correct charity wallet", async function () {
      expect(await donnyRound.charityWallet()).to.equal(charity.address);
    });

    it("Should have correct entry fee", async function () {
      expect(await donnyRound.ENTRY_FEE()).to.equal(ENTRY_FEE);
    });
  });

  describe("Enter Round", function () {
    it("Should allow player to enter round", async function () {
      await cUSD.connect(player1).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await donnyRound.connect(player1).enterRound();

      expect(await donnyRound.hasEntered(player1.address)).to.be.true;
      expect(await donnyRound.totalEntries()).to.equal(1);
    });

    it("Should start round when first player enters", async function () {
      await cUSD.connect(player1).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await donnyRound.connect(player1).enterRound();

      const roundInfo = await donnyRound.getRoundInfo();
      expect(roundInfo[0]).to.be.gt(0); // roundStartTime
      expect(roundInfo[1]).to.be.gt(roundInfo[0]); // roundEndTime
    });

    it("Should prevent double entry", async function () {
      await cUSD.connect(player1).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await donnyRound.connect(player1).enterRound();

      await expect(
        donnyRound.connect(player1).enterRound()
      ).to.be.revertedWith("Already entered");
    });

    it("Should transfer entry fee correctly", async function () {
      const initialBalance = await cUSD.balanceOf(player1.address);
      await cUSD.connect(player1).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await donnyRound.connect(player1).enterRound();

      expect(await cUSD.balanceOf(player1.address)).to.equal(
        initialBalance - ENTRY_FEE
      );
    });

    it("Should split entry fee correctly (60% prize, 40% charity)", async function () {
      await cUSD.connect(player1).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await donnyRound.connect(player1).enterRound();

      const roundInfo = await donnyRound.getRoundInfo();
      const prizePool = roundInfo[2];
      const donationPool = roundInfo[3];

      // 60% of 2 cUSD = 1.2 cUSD
      expect(prizePool).to.equal(ethers.parseEther("1.2"));
      // 40% of 2 cUSD = 0.8 cUSD
      expect(donationPool).to.equal(ethers.parseEther("0.8"));
    });
  });

  describe("Tap", function () {
    beforeEach(async function () {
      await cUSD.connect(player1).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await donnyRound.connect(player1).enterRound();
    });

    it("Should allow player to tap", async function () {
      await donnyRound.connect(player1).tap();
      expect(await donnyRound.taps(player1.address)).to.equal(1);
    });

    it("Should prevent tapping if not entered", async function () {
      await expect(
        donnyRound.connect(player2).tap()
      ).to.be.revertedWith("Not entered");
    });

    it("Should increment tap count", async function () {
      await donnyRound.connect(player1).tap();
      await donnyRound.connect(player1).tap();
      await donnyRound.connect(player1).tap();

      expect(await donnyRound.taps(player1.address)).to.equal(3);
    });
  });

  describe("Settle Round", function () {
    beforeEach(async function () {
      // Enter players
      await cUSD.connect(player1).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await cUSD.connect(player2).approve(await donnyRound.getAddress(), ENTRY_FEE);
      await cUSD.connect(player3).approve(await donnyRound.getAddress(), ENTRY_FEE);

      await donnyRound.connect(player1).enterRound();
      await donnyRound.connect(player2).enterRound();
      await donnyRound.connect(player3).enterRound();

      // Make taps
      for (let i = 0; i < 10; i++) {
        await donnyRound.connect(player1).tap();
      }
      for (let i = 0; i < 5; i++) {
        await donnyRound.connect(player2).tap();
      }
      for (let i = 0; i < 3; i++) {
        await donnyRound.connect(player3).tap();
      }
    });

    it("Should prevent settling before round ends", async function () {
      await expect(
        donnyRound.settleRound()
      ).to.be.revertedWith("Round not ended");
    });

    it("Should settle round after 24 hours", async function () {
      // Fast forward time
      await ethers.provider.send("evm_increaseTime", [24 * 60 * 60 + 1]);
      await ethers.provider.send("evm_mine", []);

      const charityBalanceBefore = await cUSD.balanceOf(charity.address);
      await donnyRound.settleRound();

      // Check charity received donation
      const charityBalanceAfter = await cUSD.balanceOf(charity.address);
      const donationAmount = charityBalanceAfter - charityBalanceBefore;
      
      // 3 players * 2 cUSD * 40% = 2.4 cUSD
      expect(donationAmount).to.equal(ethers.parseEther("2.4"));
    });

    it("Should distribute prizes correctly (3 players)", async function () {
      // Fast forward time
      await ethers.provider.send("evm_increaseTime", [24 * 60 * 60 + 1]);
      await ethers.provider.send("evm_mine", []);

      const player1BalanceBefore = await cUSD.balanceOf(player1.address);
      const player2BalanceBefore = await cUSD.balanceOf(player2.address);
      const player3BalanceBefore = await cUSD.balanceOf(player3.address);

      await donnyRound.settleRound();

      // Prize pool = 3 * 2 * 60% = 3.6 cUSD
      // 1st: 50% = 1.8 cUSD
      // 2nd: 30% = 1.08 cUSD
      // 3rd: 20% = 0.72 cUSD

      const player1BalanceAfter = await cUSD.balanceOf(player1.address);
      const player2BalanceAfter = await cUSD.balanceOf(player2.address);
      const player3BalanceAfter = await cUSD.balanceOf(player3.address);

      expect(player1BalanceAfter - player1BalanceBefore).to.equal(
        ethers.parseEther("1.8")
      );
      expect(player2BalanceAfter - player2BalanceBefore).to.equal(
        ethers.parseEther("1.08")
      );
      expect(player3BalanceAfter - player3BalanceBefore).to.equal(
        ethers.parseEther("0.72")
      );
    });
  });
});

// Mock ERC20 for testing
const MockERC20Artifact = {
  abi: [
    "constructor(string memory name, string memory symbol, uint8 decimals)",
    "function mint(address to, uint256 amount)",
    "function balanceOf(address account) view returns (uint256)",
    "function approve(address spender, uint256 amount) returns (bool)",
    "function transfer(address to, uint256 amount) returns (bool)",
  ],
  bytecode: ""
};

